-- TARGET: patto Supabase project — ref eecvvgkihtcgfikaimao
-- K-Pantry "Where to Buy" data — generated by scripts/data/build-kpantry-buy-info.mjs
-- 85 recipe-linked ingredients. Only the new columns are written (plus name_ko where it was empty, if approved).
begin;
update public.pantry_ingredients set slug = 'green-onion', romanized = 'daepa', store_level = 'common', price_tier = '$', what_it_is = 'Korean cooking leans on green onions (scallions) for both flavor and garnish. In Korea the go-to is daepa, a thick, long leek-like green onion; regular scallions do the same job.', shopping_tip = 'Pick firm, bright-green tops with no slime at the base. Korean markets sell thick daepa — use about half as many stalks as the recipe count of scallions suggests.', label_hint = 'Sold as "Green Onions" or "Scallions"; at Korean markets "대파 / Daepa (Korean Green Onion)".', substitute = 'Regular scallions work perfectly. A small leek (white and light green part) is closest to daepa in soups.', shelf_life = 'Wrap in a damp paper towel and refrigerate in a bag; about 1 week. Chopped green onion freezes well for soups.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '82a12fcf-7df6-4183-984b-de34eb5336cb';
update public.pantry_ingredients set slug = 'soy-sauce', romanized = 'ganjang', store_level = 'regular', price_tier = '$', what_it_is = 'Ganjang is Korean soy sauce. Most recipes here mean the everyday, all-purpose kind — jin-ganjang or yangjo-ganjang (naturally brewed) — used for marinades, braises and dipping sauces.', shopping_tip = 'For these recipes buy regular (jin / yangjo) soy sauce. Guk-ganjang (soup soy sauce) is a different product: lighter in color but much saltier, meant only for clear soups and namul — do not swap it 1:1.', label_hint = 'All-purpose: "진간장 / Jin Ganjang" or "양조간장 / Naturally Brewed Soy Sauce". Soup soy sauce is "국간장 / Guk Ganjang / Soy Sauce for Soup".', substitute = 'Kikkoman or any naturally brewed Japanese soy sauce works as all-purpose ganjang. If a soup calls for soup soy sauce, use regular soy sauce plus a pinch of salt.', shelf_life = 'Keeps for months after opening; refrigerate for best flavor.', buy_query = 'korean soy sauce jin ganjang', weee_query = 'korean soy sauce', buy_info_updated = '2026-11-17' where id = '5d54bd80-a9bf-4a8c-9deb-758989bc8270';
update public.pantry_ingredients set slug = 'garlic', romanized = 'maneul', store_level = 'common', price_tier = '$', what_it_is = 'Korean food uses a lot of garlic, usually minced and added raw to sauces or cooked into stews and stir-fries.', shopping_tip = 'Choose heavy, tight bulbs with no green sprouts. Korean markets sell big bags of peeled cloves, which save time if you cook Korean often.', label_hint = 'Fresh "Garlic", or "Peeled Garlic" / "Minced Garlic" in jars.', substitute = 'Jarred minced garlic is fine in stews and marinades; fresh tastes better in raw sauces.', shelf_life = 'Whole bulbs: cool, dry place for weeks. Minced: refrigerate up to a week, or freeze flat in a bag.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'ec668df9-b1c3-4334-af09-97a64b055537';
update public.pantry_ingredients set slug = 'sesame-oil', romanized = 'chamgireum', store_level = 'regular', price_tier = '$$', what_it_is = 'Chamgireum is toasted sesame oil — dark amber, intensely nutty, and used as a finishing oil for namul, bibimbap and marinades rather than for frying.', shopping_tip = 'Buy toasted (roasted) sesame oil, which is dark brown. Pale "light" or cold-pressed sesame oil has almost no flavor and will not taste right. Small bottles stay fresher.', label_hint = 'Look for "참기름 / Chamgireum", "Toasted Sesame Oil" or "Pure Sesame Oil" in a dark bottle. Avoid "blended" if possible.', substitute = 'Any toasted sesame oil from a regular store works. There is no good substitute — skip it rather than using a neutral oil, and the dish will just taste flatter.', shelf_life = 'Cool, dark place; use within 6 months of opening, or refrigerate to slow it going rancid.', buy_query = 'toasted sesame oil korean', weee_query = null, buy_info_updated = '2026-11-17' where id = 'e9d47723-ede0-4267-87de-dda05e0692e1';
update public.pantry_ingredients set slug = 'gochugaru', romanized = 'gochugaru', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Gochugaru is Korean red pepper flakes — sun-dried chili ground into bright red flakes with a fruity, slightly smoky heat that is milder than cayenne.', shopping_tip = 'Coarse flakes (gulgeun) are the all-purpose kind for kimchi, stews and stir-fries. Fine powder (goun) is for making gochujang and smooth sauces. If you only buy one, buy coarse. Look for "mild" or "hot" on the bag.', label_hint = 'Look for "고춧가루 / Gochugaru / Korean Red Pepper Powder". Coarse = "굵은", fine = "고운".', substitute = 'No true substitute. Italian crushed red pepper or cayenne are much hotter and taste different — use about a quarter of the amount, mixed with sweet paprika for color. Kimchi made this way will not taste like Korean kimchi.', shelf_life = 'Airtight in the freezer or fridge for up to a year; at room temperature it fades and darkens in a few months.', buy_query = 'gochugaru korean red pepper flakes coarse', weee_query = null, buy_info_updated = '2026-11-17' where id = 'e7f8b6dc-e11d-4a7e-9848-6f857a7c0b15';
update public.pantry_ingredients set slug = 'egg', romanized = 'gyeran', store_level = 'common', price_tier = '$', what_it_is = 'Eggs show up everywhere in Korean home cooking — fried on top of rice, rolled into gyeran-mari, or stirred into soups.', shopping_tip = 'Large eggs are the standard size these recipes assume.', label_hint = 'Sold as "Eggs".', substitute = 'Any chicken eggs.', shelf_life = 'Refrigerate; good for 3–5 weeks.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'f0abe27e-487b-46ee-aed0-7b90dc4025cf';
update public.pantry_ingredients set slug = 'sesame-seeds', romanized = 'kkae', store_level = 'regular', price_tier = '$', what_it_is = 'Toasted white sesame seeds (kkae) are sprinkled on almost every Korean side dish and mixed into sauces for a nutty crunch.', shopping_tip = 'Buy roasted/toasted white sesame seeds; raw ones taste flat. To toast raw seeds, stir them in a dry pan until golden and fragrant.', label_hint = '"Roasted Sesame Seeds" or "볶음참깨 / Roasted Sesame".', substitute = 'Any toasted sesame seeds from a regular store. Skip them if you have none — they are a garnish.', shelf_life = 'Airtight, cool place for a few months; freezer for longer.', buy_query = 'roasted white sesame seeds', weee_query = null, buy_info_updated = '2026-11-17' where id = 'd9abe5c8-41f6-4953-b948-55b6cb60ecca';
update public.pantry_ingredients set slug = 'salt', romanized = 'sogeum', store_level = 'common', price_tier = '$', what_it_is = 'Plain salt for seasoning. For kimchi and salting vegetables, Koreans use coarse sea salt (cheonilyeom), which seasons more gently than table salt.', shopping_tip = 'Fine sea salt or kosher salt for everyday cooking. For kimchi, coarse sea salt without iodine is best.', label_hint = '"Sea Salt"; for kimchi, "천일염 / Korean Coarse Sea Salt".', substitute = 'Table salt is saltier by volume — use a little less. Avoid iodized salt for kimchi, which can affect fermentation.', shelf_life = 'Keeps indefinitely.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'da02f8a1-903a-48ef-96e3-9d4b0b22452e';
update public.pantry_ingredients set slug = 'sugar', romanized = 'seoltang', store_level = 'common', price_tier = '$', what_it_is = 'Plain white sugar balances salt and heat in Korean marinades and sauces.', shopping_tip = 'Regular granulated sugar.', label_hint = '"Granulated Sugar".', substitute = 'Honey or corn syrup (oligodang / mulyeot is the Korean version) can replace part of the sugar in glazes.', shelf_life = 'Keeps indefinitely.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'ca6ef0ac-3ae3-4267-b5c6-5ed9fe7d6720';
update public.pantry_ingredients set slug = 'gochujang', romanized = 'gochujang', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Gochujang is a thick, fermented Korean red chili paste made from chili, glutinous rice and soybeans. It is spicy, sweet and savory at once, and is the base of tteokbokki, bibimbap sauce and many stews.', shopping_tip = 'Tubs are labeled by heat level — "mild" and "medium hot" suit most recipes. Check the ingredients: it should list red pepper powder and rice; Korean brands like Chung Jung One or CJ Haechandle are reliable. Many US supermarkets now carry it too.', label_hint = 'Look for "고추장 / Gochujang / Korean Red Pepper Paste" (or "Hot Pepper Paste"), usually in a red tub.', substitute = 'No good substitute — mixes like sriracha with miso or ketchup with chili flakes make the dish taste very different. Gochujang is worth ordering online.', shelf_life = 'Refrigerate after opening; keeps 1 year or more.', buy_query = 'gochujang korean red pepper paste', weee_query = null, buy_info_updated = '2026-11-17' where id = '773e542f-c4d5-4afb-9757-c597f1d8ef29';
update public.pantry_ingredients set slug = 'onion', romanized = 'yangpa', store_level = 'common', price_tier = '$', what_it_is = 'Yellow onion adds sweetness to Korean stir-fries, stews and marinades.', shopping_tip = 'Firm, dry onions with no soft spots. Yellow onions are the default.', label_hint = '"Yellow Onion".', substitute = 'White or sweet onion works the same.', shelf_life = 'Cool, dry place for weeks; cut onion in the fridge for a few days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '1e4147de-af43-47f3-a3cf-d1f66874cecc';
update public.pantry_ingredients set slug = 'rice', romanized = 'ssal', store_level = 'regular', price_tier = '$$', what_it_is = 'Korean meals are built around steamed short-grain white rice (bap), which is slightly sticky so it holds together with chopsticks.', shopping_tip = 'Buy short-grain or medium-grain white rice. Calrose rice and anything labeled "sushi rice" are the same type and are sold in most US supermarkets. Long-grain (jasmine, basmati) will not stick together, so gimbap and bibimbap will not work.', label_hint = '"Short Grain Rice", "Calrose", "Sushi Rice", or "백미 / Baekmi".', substitute = 'Calrose or sushi rice is an exact match. Jasmine rice works in a pinch for a rice bowl but not for gimbap.', shelf_life = 'Uncooked: airtight, cool place for months. Cooked rice: refrigerate 3–4 days or freeze portions.', buy_query = 'short grain rice calrose', weee_query = null, buy_info_updated = '2026-11-17' where id = 'b728d828-7a99-4d2d-9932-3eb58cff19f6';
update public.pantry_ingredients set slug = 'kimchi', romanized = 'kimchi', store_level = 'regular', price_tier = '$$', what_it_is = 'Kimchi is fermented napa cabbage seasoned with gochugaru, garlic and fish sauce. Eaten as a side dish, and cooked into stews and fried rice once it is sour.', shopping_tip = 'Look in the refrigerated section. For kimchi jjigae and fried rice, older, sourer kimchi is better — buy a jar a week early or leave it on the counter for a day. Brands from Korean markets are usually more authentic than supermarket "kimchi-style" salads.', label_hint = '"배추김치 / Napa Cabbage Kimchi" or "Mat Kimchi" (cut). Sold refrigerated.', substitute = 'Supermarket kimchi works. Sauerkraut is not a substitute — the flavor is very different.', shelf_life = 'Refrigerate; keeps for months and keeps getting sourer. Keep it pressed under its liquid.', buy_query = 'napa cabbage kimchi', weee_query = null, buy_info_updated = '2026-11-17' where id = '6a98d21c-bd3f-495e-a9ff-c4426df871c2';
update public.pantry_ingredients set slug = 'tofu', romanized = 'dubu', store_level = 'regular', price_tier = '$', what_it_is = 'Dubu is tofu — firm blocks for pan-frying and braising, softer blocks for stews.', shopping_tip = 'Firm or medium-firm tofu for frying and braising (dubu-jorim, dubu-buchim); soft or medium for jjigae. Sold in water-packed tubs in the refrigerated section.', label_hint = '"Firm Tofu", "Medium Firm Tofu", or "두부 / Dubu".', substitute = 'Any brand of regular tofu. Do not confuse with silken or "sundubu" tofu, which falls apart when fried.', shelf_life = 'After opening, cover with fresh water in the fridge and change it daily; 3–4 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '620cca0a-fb63-4165-b9cf-9ecdb94907b5';
update public.pantry_ingredients set slug = 'potato', romanized = 'gamja', store_level = 'common', price_tier = '$', what_it_is = 'Potatoes appear in Korean braises, stews and the sweet-salty side dish gamja-jorim.', shopping_tip = 'Yukon Gold or other waxy potatoes hold their shape in braises better than russets.', label_hint = '"Yukon Gold" or "Potatoes".', substitute = 'Any potato; russets fall apart more in stews.', shelf_life = 'Cool, dark place for a few weeks; not in the fridge.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '86c8dfd9-2a4e-4974-9b17-69863e829558';
update public.pantry_ingredients set slug = 'zucchini', romanized = 'aehobak', store_level = 'regular', price_tier = '$', what_it_is = 'Aehobak is Korean zucchini — paler, sweeter and more tender than the dark green kind — used in doenjang jjigae, jeon and namul.', shopping_tip = 'Korean markets sell aehobak, often in a plastic sleeve. At a regular store, pick small, firm zucchini; they are less watery.', label_hint = '"애호박 / Korean Zucchini" or "Korean Squash". Regular: "Zucchini".', substitute = 'Regular zucchini works well; it is slightly more bitter and watery. Mexican gray squash (calabacita) is closer.', shelf_life = 'Fridge, unwrapped in the crisper; about 1 week.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '7f10a943-2549-48c0-a730-f5f9c8444550';
update public.pantry_ingredients set slug = 'carrot', romanized = 'danggeun', store_level = 'common', price_tier = '$', what_it_is = 'Carrots add color and sweetness to japchae, gimbap and braises.', shopping_tip = 'Firm whole carrots julienne more neatly than baby carrots.', label_hint = '"Carrots".', substitute = 'Any carrot.', shelf_life = 'Fridge in a bag; 3–4 weeks.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '5046dba7-0a19-40c2-a62f-2d3013c6aebc';
update public.pantry_ingredients set slug = 'chicken', romanized = 'dakgogi', store_level = 'common', price_tier = '$$', what_it_is = 'Chicken for Korean braises, stir-fries and fried chicken — usually bone-in pieces or boneless thighs.', shopping_tip = 'Boneless thighs stay juicy in dakgalbi and stir-fries. For braises like jjimdak and dakdoritang, use bone-in cut-up pieces.', label_hint = '"Boneless Skinless Chicken Thighs" or "Chicken Drumsticks / Thighs".', substitute = 'Breast meat works but dries out faster — cook it a little less.', shelf_life = 'Fridge 1–2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'f8dc1aa9-bf29-4693-9b27-78743f9adccc';
update public.pantry_ingredients set slug = 'doenjang', romanized = 'doenjang', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Doenjang is Korean fermented soybean paste — chunky, salty and deeply savory, the base of doenjang jjigae and many soups.', shopping_tip = 'Sold in brown tubs next to gochujang. Do not mix it up with ssamjang (a sweeter dipping sauce made from doenjang and gochujang) — doenjang alone is plain brown paste.', label_hint = 'Look for "된장 / Doenjang / Soybean Paste".', substitute = 'Red or mixed (awase) Japanese miso is the closest. It is sweeter and smoother, so use a little more and the stew will be milder.', shelf_life = 'Refrigerate after opening; keeps for a year or more.', buy_query = 'doenjang korean soybean paste', weee_query = null, buy_info_updated = '2026-11-17' where id = '0e54ad16-2661-42d4-92cf-7b3ec05cb4ab';
update public.pantry_ingredients set slug = 'shiitake-mushroom', romanized = 'pyogo-beoseot', store_level = 'regular', price_tier = '$$', what_it_is = 'Shiitake (pyogo) mushrooms add a meaty, savory flavor to japchae, bulgogi and braises.', shopping_tip = 'Fresh shiitake are in most supermarkets. Dried shiitake are cheaper and more flavorful — soak them in warm water for 30 minutes and keep the soaking water for broth.', label_hint = '"Shiitake Mushrooms" (fresh), or "Dried Shiitake" / "표고버섯".', substitute = 'Cremini or button mushrooms, with a milder flavor.', shelf_life = 'Fresh: paper bag in the fridge, about 1 week. Dried: months in a sealed jar.', buy_query = 'dried shiitake mushrooms', weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '표고버섯') where id = '43df5f13-438e-4ead-bf05-fec9fde75bc0';
update public.pantry_ingredients set slug = 'spinach', romanized = 'sigeumchi', store_level = 'common', price_tier = '$', what_it_is = 'Spinach is blanched and seasoned for namul, and goes into bibimbap, gimbap and japchae.', shopping_tip = 'Bunched mature spinach with stems is better for namul than baby spinach, which turns mushy when blanched.', label_hint = '"Spinach" (bunched).', substitute = 'Baby spinach works if you blanch it only a few seconds.', shelf_life = 'Fridge; 3–5 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'ea1d17ba-54a6-415c-b1a6-986f0567b549';
update public.pantry_ingredients set slug = 'anchovy-broth', romanized = 'myeolchi-yuksu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Myeolchi yuksu is the everyday Korean soup stock, simmered from large dried anchovies and dried kelp (dasima). It is the base of doenjang jjigae, noodle soups and many guk.', shopping_tip = 'Buy large dried anchovies for stock (not the tiny ones for side dishes) plus a sheet of dried kelp, or grab ready-made broth tea-bag packs (yuksu packs), which are easiest.', label_hint = '"국물용 멸치 / Dried Anchovy for Broth", "다시마 / Dried Kelp", or "육수팩 / Broth Pack".', substitute = 'Japanese dashi powder or packs are the closest. Chicken or vegetable stock works but changes the flavor noticeably.', shelf_life = 'Dried anchovies: freezer for months. Made broth: fridge 3–4 days.', buy_query = 'korean anchovy broth pack dashi', weee_query = 'korean anchovy broth pack', buy_info_updated = '2026-11-17' where id = 'f7c81700-a2cf-42b5-90cb-2cadd41e9927';
update public.pantry_ingredients set slug = 'beef', romanized = 'sogogi', store_level = 'regular', price_tier = '$$$', what_it_is = 'Beef in Korean cooking is usually sliced paper-thin for bulgogi and stir-fries, or cut into chunks for soups.', shopping_tip = 'For bulgogi, ribeye or sirloin sliced very thin — Korean and Asian markets sell it pre-sliced. At home, half-freeze the meat for 30 minutes so it slices thinly. For soups, brisket or chuck.', label_hint = '"Bulgogi Beef / 불고기용" or "Thin Sliced Ribeye" at Korean markets.', substitute = 'Shaved steak (sold for cheesesteaks) is a good stand-in for pre-sliced bulgogi beef.', shelf_life = 'Fridge 1–2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '4fbd30ba-e56a-4997-ab0a-207745b832d7';
update public.pantry_ingredients set slug = 'pork-belly', romanized = 'samgyeopsal', store_level = 'regular', price_tier = '$$', what_it_is = 'Samgyeopsal is pork belly — rich layers of meat and fat, grilled on its own or used in kimchi jjigae and spicy stir-fries.', shopping_tip = 'For grilling, skinless belly sliced about 1/4 inch thick. Korean and Asian markets sell it pre-sliced; many supermarkets sell slab belly you can slice yourself.', label_hint = '"삼겹살 / Samgyeopsal / Sliced Pork Belly".', substitute = 'Pork shoulder (butt) sliced thin is leaner but works in stews and stir-fries.', shelf_life = 'Fridge 1–2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'bbc7f0a9-049b-44c6-be7e-8119b76fc319';
update public.pantry_ingredients set slug = 'soybean-sprouts', romanized = 'kongnamul', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Kongnamul are soybean sprouts — larger, crunchier and nuttier than mung bean sprouts, with a big yellow bean head. Used in namul, soups and bibimbap.', shopping_tip = 'Check for the yellow bean on top; that is how you tell them apart from mung bean sprouts. Buy crisp, white sprouts with no brown ends.', label_hint = '"콩나물 / Kongnamul / Soybean Sprouts".', substitute = 'Mung bean sprouts from a regular store are thinner and cook in less time; the dish will be less nutty.', shelf_life = 'Fridge, in water or in the bag; 2–3 days.', buy_query = null, weee_query = 'soybean sprouts', buy_info_updated = '2026-11-17' where id = '25b54ade-5123-4b7a-bd08-a5353a35b143';
update public.pantry_ingredients set slug = 'flour', romanized = 'milgaru', store_level = 'common', price_tier = '$', what_it_is = 'All-purpose flour for jeon batter and hotteok dough. Korean markets also sell ready-mixed pancake flour (buchimgaru).', shopping_tip = 'All-purpose flour works. For crispier jeon, look for Korean pancake mix (buchimgaru) or frying mix (twigim-garu).', label_hint = '"All-Purpose Flour", or "부침가루 / Korean Pancake Mix".', substitute = 'All-purpose flour with a spoon of cornstarch or rice flour for crispness.', shelf_life = 'Airtight, cool place for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '밀가루') where id = '9dfdbd8c-d01b-4076-bd76-e17b2a9e468c';
update public.pantry_ingredients set slug = 'mushroom', romanized = 'beoseot', store_level = 'common', price_tier = '$', what_it_is = 'Mixed mushrooms for stews — Korean cooks use enoki, oyster, shiitake or king oyster depending on what is around.', shopping_tip = 'Any fresh mushrooms. Enoki and king oyster mushrooms are sold in most Asian markets and many supermarkets.', label_hint = '"Mushrooms"; at Asian markets "팽이버섯 / Enoki" or "새송이 / King Oyster".', substitute = 'Button or cremini mushrooms.', shelf_life = 'Paper bag in the fridge; about 1 week (enoki 3–5 days).', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '92c68b32-a23e-436d-b523-b5c845ce0350';
update public.pantry_ingredients set slug = 'spam', romanized = 'seupaem', store_level = 'common', price_tier = '$', what_it_is = 'Canned luncheon meat, a Korean staple since the 1950s, essential in budae jjigae and great pan-fried with rice.', shopping_tip = 'Classic or Less Sodium both work; Less Sodium is easier to balance in salty stews.', label_hint = '"SPAM" or "Luncheon Meat".', substitute = 'Other canned luncheon meat, or ham.', shelf_life = 'Opened: fridge in a sealed container, 3–4 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '19fd6123-4f04-4ae8-8a18-f1cf2f811f94';
update public.pantry_ingredients set slug = 'cucumber', romanized = 'oi', store_level = 'common', price_tier = '$', what_it_is = 'Korean cucumbers are thin-skinned and crunchy, used raw in cold noodles and quick salads (oi-muchim).', shopping_tip = 'Persian or English cucumbers are closest to Korean cucumbers. Regular slicing cucumbers have thick skins and big seeds — peel and seed them.', label_hint = '"Persian Cucumbers" or "English Cucumber"; at Korean markets "백오이 / Korean Cucumber".', substitute = 'Persian or English cucumber.', shelf_life = 'Fridge; about 1 week.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '90f081f7-94db-49f2-ad63-80b807a12747';
update public.pantry_ingredients set slug = 'tteokbokki-rice-cakes', romanized = 'tteokbokki-tteok', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Tteokbokki tteok are chewy cylinder-shaped rice cakes made from rice (or wheat) flour — the base of tteokbokki and a classic add-in for budae jjigae and ramyeon.', shopping_tip = 'Buy the finger-sized cylinders (garaetteok style). Do not grab the thin oval slices — those are tteokguk tteok for rice cake soup, and they turn mushy in a spicy sauce. Rice tteok is chewier; wheat tteok is softer. Usually in the fridge or freezer section.', label_hint = '"떡볶이 떡 / Tteokbokki Rice Cake" (cylinders). Not "떡국 떡 / Sliced Rice Cake for Soup".', substitute = 'No real substitute. Sliced tteokguk tteok works if you cook it briefly. In a pinch, gnocchi gives a similar chew, though the texture is softer.', shelf_life = 'Refrigerated packs harden — soak in warm water 10 minutes before cooking. Freeze unopened packs for months.', buy_query = 'tteokbokki rice cake', weee_query = null, buy_info_updated = '2026-11-17' where id = 'edc73d2a-7971-4a71-8b08-2f6d2ba53938';
update public.pantry_ingredients set slug = 'vinegar', romanized = 'sikcho', store_level = 'common', price_tier = '$', what_it_is = 'Vinegar brightens cold noodles, quick pickles and dipping sauces.', shopping_tip = 'Rice vinegar or apple cider vinegar are the most common in Korean kitchens. Avoid "seasoned" rice vinegar, which has added sugar and salt.', label_hint = '"Rice Vinegar" (unseasoned) or "Apple Cider Vinegar".', substitute = 'White vinegar, with a pinch more sugar.', shelf_life = 'Keeps indefinitely.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'b6b6cbef-2999-49c9-a756-eb09a4f93255';
update public.pantry_ingredients set slug = 'wheat-noodles', romanized = 'guksu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Korean wheat noodles: thin somyeon for warm and cold noodle soups, and thicker kalguksu noodles for knife-cut noodle soup.', shopping_tip = 'Somyeon are very thin, dried white noodles in bundles. For kalguksu, look for fresh or frozen flat wheat noodles. For jjajangmyeon and jjamppong, thick fresh noodles are best.', label_hint = '"소면 / Somyeon", "칼국수 / Kalguksu Noodles", or "중화면 / Chinese-style Noodles".', substitute = 'Japanese somen for somyeon; udon or fresh linguine-width wheat noodles for kalguksu and jjajangmyeon.', shelf_life = 'Dried: months in the pantry. Fresh: fridge a few days or freezer.', buy_query = 'korean somyeon wheat noodles', weee_query = 'somyeon', buy_info_updated = '2026-11-17' where id = 'b6f2a450-1e98-4a40-8a30-3b6d4f9e0748';
update public.pantry_ingredients set slug = 'soft-tofu', romanized = 'sundubu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Sundubu is extra-soft, unpressed tofu, sold in tubes. It is scooped into bubbling sundubu jjigae and almost melts in the stew.', shopping_tip = 'Look for a long plastic tube in the refrigerated section of Korean markets. Squeeze it straight into the pot.', label_hint = '"순두부 / Sundubu / Soft Tofu" (tube pack).', substitute = 'Silken tofu from a regular supermarket is the best stand-in.', shelf_life = 'Fridge; use within 2 days of opening.', buy_query = null, weee_query = 'soft tofu tube', buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '순두부') where id = 'e5d7969b-f75d-4202-b2ba-b9929ed53be2';
update public.pantry_ingredients set slug = 'fish-cake', romanized = 'eomuk', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Eomuk (odeng) are Korean fish cakes — thin, chewy sheets or skewers made from fish paste, used in eomuk-tang soup, tteokbokki and stir-fried side dishes.', shopping_tip = 'Flat rectangular sheets are the most versatile. Pour boiling water over them before cooking to remove excess oil. Sold refrigerated or frozen.', label_hint = '"어묵 / Eomuk", "부산어묵", or "Fish Cake".', substitute = 'Japanese fish cakes from a Japanese or Asian market (satsuma-age, chikuwa) work well — slice them and use them the same way.', shelf_life = 'Fridge about 1 week; freezes well.', buy_query = null, weee_query = 'korean fish cake', buy_info_updated = '2026-11-17' where id = '56e8360b-5b2b-408a-82b2-145ed1d07da2';
update public.pantry_ingredients set slug = 'glass-noodles', romanized = 'dangmyeon', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Dangmyeon are Korean sweet potato starch noodles — grey when dry, glassy and springy when cooked. They are the noodle in japchae.', shopping_tip = 'Buy noodles made from 100% sweet potato starch. They are long — cut them with scissors after cooking.', label_hint = '"당면 / Dangmyeon / Sweet Potato Starch Noodles" or "Korean Vermicelli".', substitute = 'Mung bean glass noodles are thinner and softer. Rice vermicelli has a very different texture.', shelf_life = 'Dry: months in the pantry. Cooked japchae: fridge 2–3 days.', buy_query = 'dangmyeon sweet potato starch noodles', weee_query = null, buy_info_updated = '2026-11-17' where id = '3f5dcc57-9f9f-4231-9aaa-4af1ab4be0c2';
update public.pantry_ingredients set slug = 'korean-radish', romanized = 'mu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Mu is Korean radish — short, stout and pale green at the top. It is sweeter and denser than daikon, and goes into soups, braises and kkakdugi.', shopping_tip = 'Pick a heavy radish with smooth, firm skin. Korean radish is fatter than the long daikon sold in supermarkets.', label_hint = '"무 / Mu / Korean Radish".', substitute = 'Daikon from a regular store works, with a slightly more watery, peppery taste.', shelf_life = 'Wrapped in the fridge; 1–2 weeks.', buy_query = null, weee_query = 'korean radish', buy_info_updated = '2026-11-17' where id = 'b4c5a25c-b885-4bbb-8062-b3e5c2f031c2';
update public.pantry_ingredients set slug = 'seafood-mix', romanized = 'haemul', store_level = 'regular', price_tier = '$$', what_it_is = 'A frozen mix of shrimp, squid, mussels and clams — the shortcut for haemul pajeon, seafood stews and jjamppong.', shopping_tip = 'Frozen seafood medley bags are in most supermarket freezer sections. Thaw and pat dry before using in pancakes.', label_hint = '"Frozen Seafood Medley" or "해물모둠 / Mixed Seafood".', substitute = 'Shrimp plus any shellfish you like.', shelf_life = 'Frozen for months; once thawed, cook the same day.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '1647bd16-89eb-4c65-be9b-b6ee6c5f1ff5';
update public.pantry_ingredients set slug = 'american-cheese', romanized = 'seullaiseu-chijeu', store_level = 'common', price_tier = '$', what_it_is = 'A slice of processed American cheese melted on top is a classic in budae jjigae and Korean ramyeon.', shopping_tip = 'Individually wrapped American cheese slices melt the smoothest.', label_hint = '"American Cheese Slices".', substitute = 'Any easy-melting sliced cheese.', shelf_life = 'Fridge; follow the package date.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'd8486e23-772e-4836-963c-a5c0417740e8';
update public.pantry_ingredients set slug = 'cabbage', romanized = 'yangbaechu', store_level = 'common', price_tier = '$', what_it_is = 'Round green cabbage adds sweetness and crunch to stir-fries, dumpling filling and jjamppong.', shopping_tip = 'Heavy heads with tight leaves.', label_hint = '"Green Cabbage".', substitute = 'Napa cabbage works too.', shelf_life = 'Fridge; 1–2 weeks.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '05d4e7d3-cc00-465b-bbfe-1b2dcdc19428';
update public.pantry_ingredients set slug = 'korean-instant-ramen', romanized = 'ramyeon', store_level = 'regular', price_tier = '$', what_it_is = 'Korean instant ramyeon has thicker, chewier noodles and bolder soup bases than most other instant noodles.', shopping_tip = 'Shin Ramyun is the classic for budae jjigae and ramyeon upgrades; many US supermarkets stock it in the international aisle.', label_hint = '"신라면 / Shin Ramyun", or any Korean ramyeon.', substitute = 'Any instant ramen noodles; use less of the seasoning packet if it is a different brand.', shelf_life = 'Months in the pantry.', buy_query = 'shin ramyun korean instant noodles', weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '라면') where id = '6a46b5d8-d70f-47f5-921d-65313be4bc07';
update public.pantry_ingredients set slug = 'mozzarella-cheese', romanized = 'mojjarella-chijeu', store_level = 'common', price_tier = '$$', what_it_is = 'Shredded mozzarella melted over buldak, dakgalbi or fried rice is a popular modern Korean touch.', shopping_tip = 'Low-moisture shredded mozzarella melts and stretches best.', label_hint = '"Shredded Mozzarella".', substitute = 'Any melting cheese.', shelf_life = 'Fridge; about 1 week after opening.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'f3c38c62-0c7e-4a38-a5ae-2aa75baad388';
update public.pantry_ingredients set slug = 'beef-short-ribs', romanized = 'sogalbi', store_level = 'regular', price_tier = '$$$', what_it_is = 'Galbi are beef short ribs, braised low and slow in galbi-jjim or simmered into the clear soup galbitang.', shopping_tip = 'For galbi-jjim and galbitang, buy English-cut short ribs (thick chunks on the bone). LA galbi is the thin cross-cut used for grilling, not braising.', label_hint = '"Beef Short Ribs" (English cut) or "찜갈비 / Galbi for Braising".', substitute = 'Boneless short ribs or chuck roast in chunks; the broth will be less rich.', shelf_life = 'Fridge 2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '소갈비') where id = 'd82616dd-4aae-46d9-9e6f-08f9ea30fe1f';
update public.pantry_ingredients set slug = 'naengmyeon-noodles', romanized = 'naengmyeon', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Naengmyeon noodles are thin, very chewy noodles made from buckwheat and starch, served ice-cold in broth or with spicy sauce.', shopping_tip = 'Korean markets sell naengmyeon kits with the noodles and broth or sauce packets together, which is the easiest option.', label_hint = '"냉면 / Naengmyeon" or "Buckwheat Noodles for Cold Noodle".', substitute = 'Japanese soba is the closest from a regular store, but it is much softer and less chewy.', shelf_life = 'Dry or frozen for months.', buy_query = 'korean naengmyeon noodles', weee_query = 'naengmyeon', buy_info_updated = '2026-11-17' where id = 'd3c34036-3cb9-41b9-898a-c4b223cd0223';
update public.pantry_ingredients set slug = 'cornstarch', romanized = 'okusu-jeonbun', store_level = 'common', price_tier = '$', what_it_is = 'Starch for a light, crunchy coating on Korean fried chicken.', shopping_tip = 'Plain cornstarch. Potato starch makes an even crispier crust.', label_hint = '"Cornstarch" or "Potato Starch".', substitute = 'Potato starch.', shelf_life = 'Keeps indefinitely, sealed.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '옥수수 전분') where id = 'd2014c0f-685a-409a-8179-ab79bda3fbc6';
update public.pantry_ingredients set slug = 'sundae', romanized = 'sundae', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Sundae is Korean blood sausage stuffed with glass noodles and pork blood — mild, chewy and popular as street food with tteokbokki.', shopping_tip = 'Sold frozen or refrigerated at Korean markets. Steam or microwave until hot and soft before slicing.', label_hint = '"순대 / Sundae / Korean Sausage".', substitute = 'No substitute — skip it if you cannot find it.', shelf_life = 'Freezer for months; once heated, eat within a day.', buy_query = null, weee_query = 'soondae', buy_info_updated = '2026-11-17' where id = '234ed89d-5685-4b70-9ac3-56abf82e2b64';
update public.pantry_ingredients set slug = 'perilla-oil', romanized = 'deulgireum', store_level = 'korean_asian', price_tier = '$$$', what_it_is = 'Deulgireum is oil pressed from toasted perilla seeds. It has a grassy, nutty flavor distinct from sesame oil and is prized in soups, namul and fish stews.', shopping_tip = 'It is a different plant from sesame — do not confuse it with sesame oil (chamgireum). Buy small bottles; it goes rancid quickly.', label_hint = 'Look for "들기름 / Deulgireum / Perilla Oil". Not "참기름" (sesame oil).', substitute = 'No true substitute. Toasted sesame oil is the closest swap, but the dish will taste different.', shelf_life = 'Refrigerate after opening and use within 1–2 months.', buy_query = 'korean perilla oil deulgireum', weee_query = null, buy_info_updated = '2026-11-17' where id = '69d96ef3-207e-4ede-bacd-db766bc9d674';
update public.pantry_ingredients set slug = 'danmuji', romanized = 'danmuji', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Danmuji is sweet, crunchy yellow pickled radish — the bright yellow strip inside gimbap.', shopping_tip = 'For gimbap, buy pre-cut long strips (gimbap danmuji), often sold in gimbap kits with burdock root.', label_hint = '"단무지 / Danmuji / Yellow Pickled Radish". Japanese "takuan" is the same thing.', substitute = 'Japanese takuan. Without it, gimbap still works but loses its sweet crunch.', shelf_life = 'Fridge in its brine; several weeks.', buy_query = 'danmuji yellow pickled radish gimbap', weee_query = null, buy_info_updated = '2026-11-17' where id = '7d8e3a98-1825-4aa1-ba3e-b1949ec5a48f';
update public.pantry_ingredients set slug = 'pork-shoulder', romanized = 'dwaeji-apdarisal', store_level = 'regular', price_tier = '$', what_it_is = 'Pork shoulder (front leg cut) is the go-to lean-but-juicy pork for dumplings, jjajangmyeon and stir-fries.', shopping_tip = 'Pork shoulder or butt, diced or ground. For dumplings, ground pork works fine.', label_hint = '"Pork Shoulder", "Pork Butt", or "Ground Pork".', substitute = 'Ground pork for dumplings; pork belly for richer jjajang.', shelf_life = 'Fridge 1–2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '33973ca1-79e6-4d3e-870a-d78ae18b52fd';
update public.pantry_ingredients set slug = 'gim-seaweed-sheets', romanized = 'gim', store_level = 'regular', price_tier = '$', what_it_is = 'Gim is dried laver seaweed pressed into sheets. Plain roasted sheets wrap gimbap; seasoned snack sheets are eaten with rice.', shopping_tip = 'For gimbap, buy full-size plain roasted sheets labeled for gimbap or sushi. Small seasoned snack packs (with oil and salt) will tear when rolled.', label_hint = '"김밥김 / Gimbap Gim", "Roasted Seaweed", or "Sushi Nori".', substitute = 'Sushi nori from any supermarket is the same.', shelf_life = 'Sealed airtight away from moisture; months. Freeze opened packs to keep them crisp.', buy_query = 'gimbap seaweed sheets roasted', weee_query = null, buy_info_updated = '2026-11-17' where id = '6fb9c7d0-d66f-4710-9a4a-64086c33a40e';
update public.pantry_ingredients set slug = 'squid', romanized = 'ojingeo', store_level = 'regular', price_tier = '$$', what_it_is = 'Squid is stir-fried with spicy sauce in ojingeo-bokkeum and added to seafood pancakes and stews.', shopping_tip = 'Frozen cleaned squid tubes are easiest — score and cut into strips. Cook quickly; overcooked squid turns rubbery.', label_hint = '"Squid Tubes" or "오징어 / Ojingeo".', substitute = 'Shrimp, or octopus.', shelf_life = 'Frozen for months; thawed, cook the same day.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '1514aa24-aa88-4d3b-831f-f4c17ce9d6d0';
update public.pantry_ingredients set slug = 'ssamjang', romanized = 'ssamjang', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Ssamjang is a thick dipping sauce of doenjang and gochujang with garlic and sesame — the dab you put in a lettuce wrap with grilled meat.', shopping_tip = 'Sold in green tubs next to gochujang and doenjang.', label_hint = '"쌈장 / Ssamjang / Seasoned Soybean Paste".', substitute = 'Easy to make: 2 parts doenjang (or miso), 1 part gochujang, a little garlic, sesame oil and honey.', shelf_life = 'Refrigerate after opening; keeps for months.', buy_query = 'ssamjang korean dipping sauce', weee_query = null, buy_info_updated = '2026-11-17' where id = 'a48fa95b-5aff-4061-b2a0-6d0e47a7019f';
update public.pantry_ingredients set slug = 'active-dry-yeast', romanized = 'geonjo-hyomo', store_level = 'common', price_tier = '$', what_it_is = 'Yeast for hotteok dough, the chewy filled street pancake.', shopping_tip = 'Active dry or instant yeast, in the baking aisle.', label_hint = '"Active Dry Yeast" or "Instant Yeast".', substitute = 'Instant yeast — mix it straight into the flour.', shelf_life = 'Fridge after opening; several months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '드라이 이스트') where id = '587d8c29-2700-4acd-b10c-b66b401c9625';
update public.pantry_ingredients set slug = 'beef-broth', romanized = 'sogogi-yuksu', store_level = 'regular', price_tier = '$', what_it_is = 'Chilled beef broth is the base of mul-naengmyeon; it is often mixed with dongchimi (radish water kimchi) liquid for tang.', shopping_tip = 'Naengmyeon kits from Korean markets include ready-made cold broth packets. Otherwise, use low-sodium beef broth and chill it until icy.', label_hint = '"냉면 육수 / Naengmyeon Broth" or "Low Sodium Beef Broth".', substitute = 'Low-sodium beef broth with a splash of rice vinegar and a pinch of sugar.', shelf_life = 'Opened carton: fridge 4–5 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '3375ebbe-2e8f-407f-9182-60890f8eba3a';
update public.pantry_ingredients set slug = 'doraji', romanized = 'doraji', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Doraji is bellflower root — crunchy, slightly bitter white strips made into a seasoned namul side dish.', shopping_tip = 'Usually sold shredded and dried, or peeled in bags in the refrigerated section. Rub with salt and rinse to tame the bitterness.', label_hint = '"도라지 / Doraji / Bellflower Root".', substitute = 'No real substitute — the dish depends on it.', shelf_life = 'Dried: months. Fresh: fridge a few days.', buy_query = 'dried doraji bellflower root', weee_query = null, buy_info_updated = '2026-11-17' where id = '6f2714dc-14d4-42e2-9e58-ea2aeacf0701';
update public.pantry_ingredients set slug = 'chunjang', romanized = 'chunjang', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Chunjang is Korean black bean paste — a salty, roasted fermented soybean paste that becomes the glossy sauce in jjajangmyeon.', shopping_tip = 'Fry the paste in oil for a few minutes before using to remove bitterness. Some brands are pre-roasted ("볶은 춘장").', label_hint = '"춘장 / Chunjang / Black Bean Paste".', substitute = 'No good substitute. Chinese black bean sauce or Japanese dark miso will not give the same flavor.', shelf_life = 'Refrigerate after opening; keeps for months.', buy_query = 'chunjang korean black bean paste', weee_query = null, buy_info_updated = '2026-11-17' where id = '5e0683ff-1501-42d7-90dd-1290713803a1';
update public.pantry_ingredients set slug = 'black-soybeans', romanized = 'geomeunkong', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Dried black soybeans (seoritae) are simmered in soy sauce and syrup for the side dish kongjaban.', shopping_tip = 'Black soybeans have a green interior when cut. Mexican black beans (turtle beans) are a different bean.', label_hint = '"검은콩 / 서리태 / Black Soybeans".', substitute = 'Black turtle beans will work, but they are softer and fall apart more easily.', shelf_life = 'Dried: months in a sealed container.', buy_query = 'korean black soybeans', weee_query = 'dried black soybean', buy_info_updated = '2026-11-17' where id = 'e287c8ac-915e-4cf8-8775-d6b637433ad2';
update public.pantry_ingredients set slug = 'broccoli', romanized = 'beurokolli', store_level = 'common', price_tier = '$', what_it_is = 'Blanched broccoli seasoned with sesame oil makes a quick namul-style side dish.', shopping_tip = 'Tight, deep-green florets.', label_hint = '"Broccoli".', substitute = 'Broccolini.', shelf_life = 'Fridge; 4–5 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '265a5666-440c-4c55-b05f-b54cf760b1bf';
update public.pantry_ingredients set slug = 'brown-sugar', romanized = 'heuksetang', store_level = 'common', price_tier = '$', what_it_is = 'Brown sugar with cinnamon is the melty filling of hotteok.', shopping_tip = 'Dark or light brown sugar both work; dark is richer.', label_hint = '"Brown Sugar".', substitute = 'White sugar with a little honey or molasses.', shelf_life = 'Airtight to keep it soft; keeps indefinitely.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '흑설탕') where id = 'ebdad443-8fc7-43d7-a505-77efb5849a9f';
update public.pantry_ingredients set slug = 'canned-tuna', romanized = 'chamchi', store_level = 'common', price_tier = '$', what_it_is = 'Korean pantry tuna is usually packed in oil and goes into tuna-mayo rice bowls, kimchi stew and gimbap.', shopping_tip = 'Tuna in oil is richer and closer to Korean brands (like Dongwon); drain it well.', label_hint = '"Tuna in Oil" or "동원참치 / Dongwon Tuna".', substitute = 'Tuna in water — add a little oil or mayo.', shelf_life = 'Opened: fridge, covered, 2–3 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'e52179cf-7146-40a0-b6a6-850a8d62cb72';
update public.pantry_ingredients set slug = 'cinnamon', romanized = 'gyepi', store_level = 'common', price_tier = '$', what_it_is = 'Ground cinnamon flavors the sweet hotteok filling.', shopping_tip = 'Ground cinnamon from the spice aisle.', label_hint = '"Ground Cinnamon".', substitute = 'Any ground cinnamon.', shelf_life = 'Sealed; flavor fades after about a year.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '9d7db902-8bdd-42ef-b9fe-0bd73e617cc6';
update public.pantry_ingredients set slug = 'imitation-crab', romanized = 'gematsal', store_level = 'regular', price_tier = '$', what_it_is = 'Imitation crab sticks (surimi) are a standard gimbap filling.', shopping_tip = 'Long sticks are easiest for gimbap; flake-style works in salads.', label_hint = '"Imitation Crab" or "Crab Sticks".', substitute = 'Skip it, or use a strip of egg omelet.', shelf_life = 'Fridge; 3 days after opening.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '2abdbc2a-1d0d-42e6-8d50-d6427261a19b';
update public.pantry_ingredients set slug = 'korean-curry-powder', romanized = 'kare-garu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Korean curry is a mild, yellow, turmeric-forward curry mix — most often Ottogi brand — that thickens into a sauce for curry rice.', shopping_tip = 'Buy curry powder mix (not plain spice). Ottogi comes in mild, medium and hot.', label_hint = '"오뚜기 카레 / Ottogi Curry" (powder mix).', substitute = 'Japanese curry roux blocks are the closest — they are a little sweeter and darker. Indian curry powder is a different flavor.', shelf_life = 'Months in a sealed container.', buy_query = 'ottogi korean curry powder', weee_query = null, buy_info_updated = '2026-11-17' where id = '983ffc59-4b8b-4936-a879-65e3ff1f1ea0';
update public.pantry_ingredients set slug = 'jujubes', romanized = 'daechu', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Daechu are dried red jujubes, slightly sweet and apple-like, simmered in samgyetang and other tonic soups.', shopping_tip = 'Choose plump, glossy, deep-red jujubes. Often sold near ginseng at Korean markets.', label_hint = '"대추 / Daechu / Dried Jujube" or "Red Dates".', substitute = 'Leave them out; the soup will be a little less sweet. One date can stand in for a few jujubes.', shelf_life = 'Airtight, fridge or freezer for months.', buy_query = 'dried red jujube korean', weee_query = null, buy_info_updated = '2026-11-17' where id = '80de0a12-2364-4c02-b37d-cc2e91638554';
update public.pantry_ingredients set slug = 'miyeok', romanized = 'miyeok', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Miyeok is dried wakame seaweed, rehydrated for miyeok-guk — the birthday seaweed soup.', shopping_tip = 'Dried cut wakame expands a lot — a small handful is enough for a pot. Different from gim (roasted sheets) and dasima (kelp).', label_hint = '"미역 / Miyeok / Dried Seaweed for Soup" or "Wakame".', substitute = 'Japanese wakame is the same seaweed.', shelf_life = 'Dry: months in a sealed bag.', buy_query = 'dried miyeok wakame seaweed soup', weee_query = 'dried seaweed wakame', buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '미역') where id = '1af67854-c7e7-42f6-835a-857285644ecf';
update public.pantry_ingredients set slug = 'dumpling-wrappers', romanized = 'mandupi', store_level = 'regular', price_tier = '$', what_it_is = 'Round wheat wrappers for mandu (Korean dumplings).', shopping_tip = 'Round "gyoza" or "dumpling" wrappers in the refrigerated or freezer section. Square wonton wrappers are thinner but work.', label_hint = '"만두피 / Mandu Wrappers" or "Gyoza Wrappers".', substitute = 'Gyoza or wonton wrappers.', shelf_life = 'Fridge a few days after opening; freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '0c987e38-b4fe-4cec-9444-3c43695c3ead';
update public.pantry_ingredients set slug = 'eggplant', romanized = 'gaji', store_level = 'regular', price_tier = '$', what_it_is = 'Long, slim Asian eggplants are steamed and seasoned for gaji-namul.', shopping_tip = 'Chinese or Japanese eggplants are thinner-skinned and less bitter than the big globe kind.', label_hint = '"Chinese Eggplant", "Japanese Eggplant", or "가지".', substitute = 'Globe eggplant, peeled.', shelf_life = 'Fridge; 3–4 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '415cf218-e8ec-435c-8bb6-1ff1a0c61108';
update public.pantry_ingredients set slug = 'fish-roe', romanized = 'al', store_level = 'korean_asian', price_tier = '$$$', what_it_is = 'Pollock roe (al) is simmered in the spicy stew altang.', shopping_tip = 'Frozen pollock roe is sold at Korean and Japanese markets. Thaw in the fridge.', label_hint = '"명태알 / Pollock Roe" or "알탕용".', substitute = 'Mentaiko from a Japanese market is pollock roe too and works well (it is pre-seasoned and a little spicy, so add less salt). Plain tarako is even closer.', shelf_life = 'Frozen for months; cook within a day of thawing.', buy_query = null, weee_query = 'pollock roe', buy_info_updated = '2026-11-17' where id = '1d30b9f8-a928-4cb9-af1e-38da53664be5';
update public.pantry_ingredients set slug = 'korean-fish-sauce', romanized = 'aekjeot', store_level = 'korean_asian', price_tier = '$$', what_it_is = 'Aekjeot is Korean fish sauce, essential for kimchi. Myeolchi-aekjeot (anchovy) is the standard; kkanari-aekjeot (sand lance) is a bit lighter and cleaner.', shopping_tip = 'For kimchi, anchovy fish sauce (myeolchi-aekjeot) is the default. Sand lance (kkanari) is fine too — they can be swapped 1:1.', label_hint = '"멸치액젓 / Anchovy Fish Sauce" or "까나리액젓 / Sand Lance Fish Sauce".', substitute = 'Thai or Vietnamese fish sauce (e.g. Red Boat, Three Crabs) from a regular store works — it is a little saltier, so start with less.', shelf_life = 'Months at room temperature; fridge for best flavor.', buy_query = 'korean anchovy fish sauce myeolchi aekjeot', weee_query = 'korean fish sauce', buy_info_updated = '2026-11-17' where id = 'c3caf419-ca34-4fc7-8613-06111507db42';
update public.pantry_ingredients set slug = 'garlic-chives', romanized = 'buchu', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Buchu are Korean garlic chives — flat, garlicky greens fried into buchu-jeon pancakes and kimchi.', shopping_tip = 'Flat leaves, bright green, no yellowing. Sold in bunches at Korean and Chinese markets.', label_hint = '"부추 / Buchu", "Garlic Chives", or "Chinese Chives".', substitute = 'Scallions, thinly sliced lengthwise — less garlicky.', shelf_life = 'Fridge in a damp paper towel; 3–4 days.', buy_query = null, weee_query = 'garlic chives', buy_info_updated = '2026-11-17' where id = '896eb9d3-3e27-4ded-a8a0-4997fad0a4e8';
update public.pantry_ingredients set slug = 'ginger', romanized = 'saenggang', store_level = 'common', price_tier = '$', what_it_is = 'Fresh ginger is grated into kimchi paste and marinades.', shopping_tip = 'Firm, smooth knobs with tight skin.', label_hint = '"Ginger Root".', substitute = 'Jarred minced ginger.', shelf_life = 'Fridge for weeks, or freeze and grate frozen.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = 'c757077b-637d-4e3d-af8e-e017e7988c08';
update public.pantry_ingredients set slug = 'ginseng', romanized = 'insam', store_level = 'korean_asian', price_tier = '$$$', what_it_is = 'Fresh Korean ginseng root is simmered whole in samgyetang for its earthy, bitter-sweet flavor.', shopping_tip = 'Fresh roots (susam) are sold at Korean markets, often in packs for samgyetang with jujubes and garlic.', label_hint = '"수삼 / Fresh Ginseng" or "삼계탕 재료 / Samgyetang Kit".', substitute = 'Dried ginseng slices. Or leave it out — the soup will still be good, just less herbal.', shelf_life = 'Fresh: fridge about 2 weeks.', buy_query = 'samgyetang ginseng soup ingredients', weee_query = null, buy_info_updated = '2026-11-17' where id = '43f32792-f5c4-4d2d-b25e-885066a32ab8';
update public.pantry_ingredients set slug = 'ketchup', romanized = 'kecheop', store_level = 'common', price_tier = '$', what_it_is = 'Ketchup flavors the rice and the classic topping of Korean omurice.', shopping_tip = 'Any regular ketchup.', label_hint = '"Ketchup".', substitute = 'Any tomato ketchup.', shelf_life = 'Fridge after opening; months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '7c659f1a-da43-4187-8ca4-94d7c982da55';
update public.pantry_ingredients set slug = 'korean-mustard', romanized = 'gyeoja', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Gyeoja is sharp, nose-tingling Korean hot mustard, stirred into cold naengmyeon broth.', shopping_tip = 'Sold in small tubes, or as powder you mix with water.', label_hint = '"연겨자 / Yeon-gyeoja / Korean Mustard".', substitute = 'Chinese hot mustard or English mustard powder. Yellow American mustard is too mild.', shelf_life = 'Fridge after opening.', buy_query = null, weee_query = 'korean mustard', buy_info_updated = '2026-11-17' where id = '514c011f-45cb-426b-b923-4437d1c29461';
update public.pantry_ingredients set slug = 'lettuce-for-ssam', romanized = 'sangchu', store_level = 'common', price_tier = '$', what_it_is = 'Soft leaf lettuce (sangchu) is used to wrap grilled meat for ssam, often with perilla leaves.', shopping_tip = 'Red or green leaf lettuce. Korean markets sell red lettuce and perilla leaves (kkaennip) together.', label_hint = '"Red Leaf Lettuce" or "상추 / Sangchu".', substitute = 'Butter or romaine lettuce.', shelf_life = 'Fridge wrapped in a damp towel; 3–5 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '8b075677-b224-40e1-80df-ac3147b01a9a';
update public.pantry_ingredients set slug = 'mayonnaise', romanized = 'mayoneujeu', store_level = 'common', price_tier = '$', what_it_is = 'Mayonnaise mixed with tuna makes the popular chamchi-mayo rice bowl.', shopping_tip = 'Any regular mayo; Japanese Kewpie is richer and slightly sweeter, closer to Korean mayo.', label_hint = '"Mayonnaise".', substitute = 'Any mayonnaise.', shelf_life = 'Fridge after opening; about 2 months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '65f48e3d-ca29-46a4-b35e-588eda45a2ac';
update public.pantry_ingredients set slug = 'mung-bean-sprouts', romanized = 'sukju', store_level = 'regular', price_tier = '$', what_it_is = 'Sukju are mung bean sprouts — thinner and more delicate than soybean sprouts, with no big bean head.', shopping_tip = 'Crisp and white with no brown ends. Most supermarkets carry them as "bean sprouts."', label_hint = '"Bean Sprouts" or "숙주 / Sukju".', substitute = 'Any fresh mung bean sprouts.', shelf_life = 'Fridge; 2–3 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '977d14c5-a62c-499c-9b39-fb6cd4a9461f';
update public.pantry_ingredients set slug = 'napa-cabbage', romanized = 'baechu', store_level = 'regular', price_tier = '$', what_it_is = 'Baechu (napa cabbage) is the cabbage of classic kimchi — long, pale, crinkly leaves with juicy white ribs.', shopping_tip = 'Heavy heads with tight, fresh leaves. Most supermarkets sell napa cabbage.', label_hint = '"Napa Cabbage" or "배추 / Baechu".', substitute = 'Napa from any store is the same. Green cabbage makes a different (tougher) kimchi.', shelf_life = 'Fridge; 1–2 weeks.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '18b8c293-3274-4f6e-bf7b-141b8597dc9a';
update public.pantry_ingredients set slug = 'oxtail', romanized = 'sokkori', store_level = 'regular', price_tier = '$$$', what_it_is = 'Oxtail is simmered for hours to make kkori-gomtang, a rich milky beef soup.', shopping_tip = 'Pick meaty pieces. Soak in cold water for an hour and blanch before simmering for a cleaner broth.', label_hint = '"Oxtail" or "소꼬리".', substitute = 'Beef shank or short ribs.', shelf_life = 'Fridge 2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '708c9824-c576-4734-90e0-2fb14e9a6eab';
update public.pantry_ingredients set slug = 'peanuts', romanized = 'ttangkong', store_level = 'common', price_tier = '$', what_it_is = 'Chopped roasted peanuts add crunch to hotteok filling.', shopping_tip = 'Unsalted roasted peanuts.', label_hint = '"Roasted Peanuts".', substitute = 'Walnuts or sunflower seeds.', shelf_life = 'Airtight for a few months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '97053207-ec2e-40be-b27f-cfff402da27c';
update public.pantry_ingredients set slug = 'pork-neck-bones', romanized = 'dwaeji-deungppyeo', store_level = 'regular', price_tier = '$', what_it_is = 'Pork neck bones (deungppyeo) are simmered for hours with potatoes for gamja-tang.', shopping_tip = 'Often sold in Latino and Asian markets as well as Korean ones. Soak in cold water to draw out blood, then blanch.', label_hint = '"Pork Neck Bones" or "감자탕용 등뼈".', substitute = 'Pork spare ribs.', shelf_life = 'Fridge 2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '돼지 등뼈') where id = 'a6e7f461-e552-4606-8def-f6abd70ab89f';
update public.pantry_ingredients set slug = 'pork-ribs', romanized = 'dwaeji-galbi', store_level = 'regular', price_tier = '$$', what_it_is = 'Pork ribs marinated in sweet soy sauce for dwaeji-galbi.', shopping_tip = 'Korean markets sell ribs butterflied thin for galbi. Spare ribs cut between the bones also work.', label_hint = '"돼지갈비 / Pork Galbi" or "Pork Spare Ribs".', substitute = 'Pork shoulder slices.', shelf_life = 'Fridge 2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17', name_ko = coalesce(nullif(name_ko, ''), '돼지갈비') where id = '2c745eba-a793-4603-8ff4-bdb61b80bfd9';
update public.pantry_ingredients set slug = 'soy-milk', romanized = 'duyu', store_level = 'regular', price_tier = '$', what_it_is = 'Unsweetened soy milk is a shortcut base for kongguksu, the chilled soybean noodle soup.', shopping_tip = 'Plain, unsweetened soy milk — sweetened or vanilla will not work.', label_hint = '"Unsweetened Soy Milk".', substitute = 'Blend soaked, boiled soybeans with water for the traditional version.', shelf_life = 'Fridge after opening; 7–10 days.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '370f5f18-1699-452e-999d-81f8c9adcb97';
update public.pantry_ingredients set slug = 'kongbiji', romanized = 'kongbiji', store_level = 'korean_asian', price_tier = '$', what_it_is = 'Kongbiji is ground soybeans (or okara, the pulp left after making tofu), simmered into the creamy stew kongbiji-jjigae.', shopping_tip = 'Korean markets sell it fresh or frozen in tubs. Japanese markets sell okara.', label_hint = '"콩비지 / Kongbiji" or "Okara".', substitute = 'Soak dried soybeans overnight and blend with a little water.', shelf_life = 'Fridge 2–3 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '60e8f479-20de-498a-84c9-886a6437056b';
update public.pantry_ingredients set slug = 'tomato', romanized = 'tomato', store_level = 'common', price_tier = '$', what_it_is = 'Sliced tomato is a fresh garnish on kongguksu.', shopping_tip = 'Ripe tomatoes or cherry tomatoes.', label_hint = '"Tomatoes".', substitute = 'Cucumber, or skip it.', shelf_life = 'Room temperature until ripe.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '7736c739-ee15-405b-8b08-d165f1088f40';
update public.pantry_ingredients set slug = 'whole-chicken', romanized = 'tongdak', store_level = 'regular', price_tier = '$$', what_it_is = 'A small whole chicken is stuffed with rice and simmered whole for samgyetang.', shopping_tip = 'Look for a small young chicken — Cornish game hens are the perfect size for one person.', label_hint = '"Cornish Game Hen" or "삼계탕용 영계 / Young Chicken".', substitute = 'Cornish hen, or bone-in chicken thighs.', shelf_life = 'Fridge 1–2 days, freezer for months.', buy_query = null, weee_query = null, buy_info_updated = '2026-11-17' where id = '989b621c-a937-4271-8819-f0272bdf641f';
